  invoiceAmount: require(path.join(OLD, 'invoiceAmount.js')).invoiceAmount,
  reportAmount: require(path.join(OLD, 'reportAmount.js')).reportAmount,
  renderInvoice: require(path.join(OLD, 'invoice.js')).renderInvoice,
  renderReport: require(path.join(OLD, 'report.js')).renderReport,
};
const newMod = {
  formatAmount: require(path.join(NEW, 'money.js')).formatAmount,
  renderInvoice: require(path.join(NEW, 'invoice.js')).renderInvoice,
  renderReport: require(path.join(NEW, 'report.js')).renderReport,
};
function mulberry32(a) { return function () { a |= 0; a = a + 0x6D2B79F5 | 0; let t = Math.imul(a ^ a >>> 15, 1 | a); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
const rnd = mulberry32(12345);
const randInt = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));
const randSafe = () => { const mag = Math.floor(rnd() * Number.MAX_SAFE_INTEGER); return rnd() < 0.5 ? -mag : mag; };

let checked = 0, mismatches = 0;
const same = (what, a, b) => { checked++; if (a !== b) { mismatches++; if (mismatches <= 10) console.log('MISMATCH', what, JSON.stringify(a), JSON.stringify(b)); } };

// 1. Every integer in a wide window, and random safe integers: new formatAmount == both old helpers.
for (let c = -300000; c <= 300000; c++) { same('win inv ' + c, oldMod.invoiceAmount(c), newMod.formatAmount(c)); same('win rep ' + c, oldMod.reportAmount(c), newMod.formatAmount(c)); }
for (let i = 0; i < 300000; i++) { const c = randSafe(); same('safe ' + c, oldMod.invoiceAmount(c), newMod.formatAmount(c)); same('safe rep ' + c, oldMod.reportAmount(c), newMod.formatAmount(c)); }
// 2. Non-integers, specials, and huge values: output must still match the old code exactly.
const weird = [0.5, 1.5, -0.5, 99.999, -99.999, 1e21, -1e21, 1e23, -1e23, 1e300, -1e300, NaN, Infinity, -Infinity, -0, 2 ** 53, 2 ** 53 + 2, 1e18 + 1, 123456789.5];
for (let i = 0; i < 100000; i++) weird.push(rnd() * 2e16 - 1e16, (rnd() - 0.5) * 1000);
for (const c of weird) same('weird ' + c, oldMod.invoiceAmount(c), newMod.formatAmount(c));
// 3. Renderers: random rows (incl. empty, single, negative, zero), exact output and order.
const ids = ['a', 'inv-1', '', 'Z9', 'long identifier'];
for (let i = 0; i < 20000; i++) {
  const rows = Array.from({ length: randInt(0, 6) }, () => ({ id: ids[randInt(0, ids.length - 1)], cents: randInt(-500000, 500000) }));
  same('renderReport ' + JSON.stringify(rows), oldMod.renderReport(rows), newMod.renderReport(rows));
  const id = ids[i % ids.length], c = randInt(-500000, 500000);
  same('renderInvoice ' + id + ' ' + c, oldMod.renderInvoice(id, c), newMod.renderInvoice(id, c));
}
console.log(`differential: compared ${checked} outputs, mismatches: ${mismatches}`);

// 4. Informational: shared arithmetic vs an exact BigInt reference of the same integer.
const exact = c => { const b = BigInt(c), neg = b < 0n, a = neg ? -b : b; return (neg ? '-' : '') + (a / 100n) + '.' + (a % 100n).toString().padStart(2, '0'); };
let safeBad = 0;
for (let c = Number.MAX_SAFE_INTEGER - 2000000; c <= Number.MAX_SAFE_INTEGER; c++) if (newMod.formatAmount(c) !== exact(c)) safeBad++;
for (let i = 0; i < 300000; i++) { const c = randSafe(); if (newMod.formatAmount(c) !== exact(c)) safeBad++; }
let bigBad = 0, bigEx = null; const bigTotal = 300000;
for (let i = 0; i < bigTotal; i++) { const c = Math.floor(rnd() * 1e18); if (newMod.formatAmount(c) !== exact(c)) { bigBad++; bigEx ??= [c, newMod.formatAmount(c), exact(c)]; } }
